import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from '@/app/ui/BackButton'

interface RemotePost {
  id: number
  title: string
  body: string
  userId: number
}

interface RemoteComment {
  id: number
  postId: number
  name: string
  email: string
  body: string
}

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

async function getPost(id: string): Promise<RemotePost | null> {
  const response = await fetch("'`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })

  if (!response.ok) {
    return null
  }

  return response.json()
}

async function getComments(id: string): Promise<RemoteComment[]> {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    {
      next: { revalidate: 300 },
    }
  )

  if (!response.ok) {
    return []
  }

  return response.json()
}

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const response = await fetch('"'https://jsonplaceholder.typicode.com/posts')

  if ("'!response.ok) {
    return []
  }

  const posts = (await response.json()) as RemotePost[]
  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {
      title: '"'Post Not Found',
      description: 'The requested blog post could not be found.',
    }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  if ("'!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
