interface SinglePostRecord {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface UpdatePostPayload {
  title?: unknown
  content?: unknown
}

interface RouteContext {
  params: Promise<{ id: string }>
}

function parsePostId(rawId: string): number | null {
  const parsed = Number.parseInt(rawId, 10)
  return Number.isFinite(parsed) ? parsed : null
}

export async function GET(_request: Request, context: RouteContext) {
  const { id } = await context.params
  const parsedId = parsePostId(id)

  if (parsedId === null) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 })
  }

  const post: SinglePostRecord = {
    id: parsedId,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: Request, context: RouteContext) {
  const { id } = await context.params
  const parsedId = parsePostId(id)

  if (parsedId === null) {
    return Response.json({ error: '"'Invalid post id' }, { status: 400 })
  }

  let payload: UpdatePostPayload

  try {
    payload = (await request.json()) as UpdatePostPayload
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const title =
    typeof payload.title === 'string' && payload.title.trim()
      ? payload.title.trim()
      : "'`Post ${id}`

  const content =
